<?php $title='Packages';include 'includes/header.php';$rows=db()->query('SELECT * FROM service_packages WHERE status=1')->fetchAll();?><section class="section"><div class="container"><p class="gold">PACKAGES</p><h1>Choose Your Level</h1><div class="row g-4 mt-3"><?php foreach($rows as $p):?><div class="col-md-3"><div class="card p-4 h-100"><h3 class="gold"><?=e($p['name'])?></h3><h4><?=number_format($p['price'],2)?> ETB</h4><p class="text-secondary"><?=e($p['description'])?></p><p><strong>Duration:</strong> <?=e($p['duration'])?></p><ul><?php foreach(explode('|',$p['features']) as $f):?><li><?=e($f)?></li><?php endforeach;?></ul><a class="btn btn-gold mt-auto" href="service_request.php">Request</a></div></div><?php endforeach;?></div></div></section><?php include 'includes/footer.php';?>
